from contextlib import contextmanager
from inspect import currentframe
from logging import Logger
from os.path import basename

from ta_emss.utilities.EmssFileLogger import EmssFileLogger

from ta_logcollector.settings import SERVER_HOST
from ta_logcollector.logger import get_net_logger
from ta_logcollector.utils.emss import get_emss_connection

logger = Logger("LC")


def _start_emss_console_log_collection(emss_loggers):
    logger.debug("Loggers: {}".format(emss_loggers))
    for emss_logger in emss_loggers:
        emss_logger.start_emss_logging()
        is_logger_alive = True if emss_logger.proc.poll() is None else False
        logger.debug(
            "Started EMSSim console logging for {}:{} [PID:{}, alive={}]".format(
                emss_logger.emss_host, emss_logger.emss_port, emss_logger.proc.pid, is_logger_alive
            )
        )


def _stop_emss_console_log_collection(emss_loggers):
    logger.debug("Loggers: {}".format(emss_loggers))
    for emss_logger in emss_loggers:
        pid = emss_logger.proc.pid
        emss_logger.stop_emss_logging()
        logger.debug(
            "Stopped EMSSim console logging for {}:{} [PID:{}]".format(
                emss_logger.emss_host, emss_logger.emss_port, pid
            )
        )


def _create_emss_loggers_instances(emss_conf, log_dir):
    # type: (dict, str) -> List[EmssFileLogger]
    emss_loggers = []
    for emss, emss_id in get_emss_connection(logger, emss_conf, 4000):
        emss_loggers.append(_create_emss_file_logger(emss_id, emss_conf, log_dir))
    return emss_loggers


def _create_emss_file_logger(bts_id, emss_conf, log_dir):
    emss_logger = EmssFileLogger(emss_conf["ip"], 7000 + bts_id)
    emss_logger.set_filepath(log_dir, "emss_{}".format(bts_id))
    return emss_logger


def start(emssim_loggers):
    """
    Method to start emssim loggers
    :param emssim_loggers:
    """
    logger.info("inside {} before start".format(basename(__file__)))
    _start_emss_console_log_collection(emssim_loggers)
    logger.info("inside {} after start".format(basename(__file__)))


def stop(emssim_loggers):
    """
    Method to stop emssim loggers
    :param emssim_loggers:
    """
    logger.info("inside {} before stop".format(basename(__file__)))
    _stop_emss_console_log_collection(emssim_loggers)
    logger.info("inside {} after stop".format(basename(__file__)))


@contextmanager
def emss(log_host, log_port, emss_conf, **kwargs):
    # type: (str, int, dict, dict) -> None
    """
    TBD, just for py.test check

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    :param emss_conf:
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(currentframe().f_code.co_name, SERVER_HOST))
    logger.debug("emss_conf = {} kwargs = {}".format(emss_conf, kwargs))
    log_dir = kwargs.pop("log_dir")
    emssim_loggers = _create_emss_loggers_instances(emss_conf, log_dir)
    try:
        start(emssim_loggers)
        yield
    finally:
        stop(emssim_loggers)
